const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Paradise, California location
  const paradiseCoords = [-121.62, 39.76];
  const geometry = ee.Geometry.Point(paradiseCoords);
  const roi = geometry.buffer(15000); // 15 km buffer around Paradise

  // Define date range: November 7-10, 2018
  const startDate = '2018-11-07';
  const endDate = '2018-11-10';

  // Load MODIS Active Fire Product (MOD14)
  const fireCollection = ee.ImageCollection('MODIS/006/MOD14A1')
    .filterDate(startDate, endDate)
    .filterBounds(roi);

  // Check if collection has data
  const collectionSize = await fireCollection.size().getInfo();
  console.log(`MODIS Fire Images Found: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log('No MODIS data found. Attempting Sentinel-2 thermal/burn area analysis...');
    const sentinel2 = ee.ImageCollection('COPERNICUS/S2_SR')
      .filterDate(startDate, endDate)
      .filterBounds(roi);

    const s2Size = await sentinel2.size().getInfo();
    console.log(`Sentinel-2 Images Found: ${s2Size}`);

    if (s2Size === 0) {
      console.log('No satellite data available for date/location.');
      console.log('C1');
      return;
    }
  }

  // Extract fire detections from MODIS
  const fireDetections = fireCollection.map(function(img) {
    return img.select('FireMask');
  });

  // Count fire pixels (FireMask: 0=no fire, 1-4=fire with varying confidence)
  const firePixelCount = fireDetections.map(function(img) {
    const fireMask = img.gte(1); // Fire if FireMask >= 1
    return img.addBands(fireMask.rename('fire_present'));
  }).select('fire_present');

  const stats = await firePixelCount.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: roi,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const firePixels = stats['fire_present'] || 0;
  console.log(`Fire Pixels Detected: ${firePixels}`);

  // Get confidence statistics if available
  const confidenceStats = await fireCollection.first().select('MaxFRP').reduceRegion({
    reducer: ee.Reducer.max(),
    geometry: roi,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const maxFireRadiativePower = confidenceStats['MaxFRP'] || 0;
  console.log(`Max Fire Radiative Power (MW): ${maxFireRadiativePower.toFixed(2)}`);

  // Validation and final answer
  if (collectionSize > 0 && firePixels > 0) {
    console.log('Active fire detected in Paradise, CA area during Nov 7-10, 2018');
    console.log('A');
  } else if (collectionSize > 0 && firePixels === 0) {
    console.log('No fire pixels detected despite valid satellite coverage.');
    console.log('B');
  } else {
    console.log('Unable to determine - data retrieval issues.');
    console.log('C3');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
